    },
    {
      "indicator": "MM200",
      "reading": "≈ R$32.65 (descendente)",
      "interpretation": "Tendência de longo prazo baixista — preço abaixo da MM200 é sinal estrutural negativo."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$29.95 (próxima à EMA21)",
      "interpretation": "Reação de curto prazo neutra/ligeramente negativa; cruzamentos recentes sem força."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$30.10 (próxima/ligeramente acima da EMA9)",
